import { EditorSignaturePad } from "@/components/design-for-ai/editor-signature-pad";

<EditorSignaturePad
  title="Mutual NDA"
  parties={parties}
  openId="jordan"
  onChange={(id, strokes) => save(id, strokes)}
/>

// The open plate takes pointer ink. Strokes are normalized 0–1 points with timestamps, so a fast pen draws thin.
// Undo drops the last stroke, Clear empties the plate, Replay draws the mark again, Export downloads an SVG.
// ⌘Z undoes. On a narrow container the two plates stack.
